SELECT new_id, id, work_id, client_id, channel_id, original_id, content_type, input_data_id, sample_data_type, original_text_scene, brand_code_name, car_series_name, label_type, label_type_level_first, label_type_level_second, label_type_level_three, label_type_level_four, label_type_level_five, scenario, sentiment, intention_type, topic, opinion, subject, fault_level, description, sentiment_score, keywords, publish_time, create_time, abandon, hit_rules, done, ext_fields, biz_ext_attrs, biz_ext_attrs2, biz_ext_attrs3 FROM dwd_voc2_post_rules_result_data where client_id = #{clientId}
and work_id in
#{item}
and abandon in
#{item}
and date(publish_time) BETWEEN DATE(#{startTime}) and DATE(#{endTime})
and date(create_time) BETWEEN DATE(#{date}) and DATE(#{date})
and sentiment in
#{item}
and intention_type in
#{item}
and brand_code_name in
#{item}
and car_series_name in
#{item}
and label_type_level_four in
#{item}
and channel_id in
#{item}
and ( trim(biz_ext_attrs -> '$.category_1') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.category_2') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.category_3') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.category_4') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.category_5') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.abstract') like concat('%',#{keywords},'%') or trim(biz_ext_attrs -> '$.serverorder') like concat('%',#{keywords},'%') or original_text_scene like concat('%',#{keywords},'%') )
and ext_fields->'$.showType' = #{showType}
order by new_id desc

SELECT prod.new_id, prod.id, prod.work_id, prod.client_id, prod.channel_id, prod.original_id, prod.content_type, prod.input_data_id, prod.sample_data_type, prod.original_text_scene, prod.brand_code_name, prod.car_series_name, label_type, label_type_level_first, label_type_level_second, label_type_level_three, label_type_level_four, label_type_level_five, prod.scenario, prod.sentiment, prod.intention_type, prod.topic, prod.opinion, prod.subject, prod.fault_level, prod.description, prod.sentiment_score, prod.keywords, prod.publish_time, prod.create_time, prod.update_time, prod.abandon, prod.hit_rules, prod.done, ext_fields, biz_ext_attrs, biz_ext_attrs2, biz_ext_attrs3, meta.data -> '$.uRL' as url FROM dwd_voc2_post_rules_result_data prod left join ays_meta_data_analysis meta on prod.original_id = meta.new_id where prod.client_id = #{paramModel.clientId}
and date(prod.publish_time) BETWEEN DATE(#{paramModel.startTime}) and DATE(#{paramModel.endTime})
and prod.sentiment in
#{item}
and prod.intention_type in
#{item}
and prod.brand_code_name in
#{item}
and prod.car_series_name in
#{item}
and prod.label_type_level_four in
#{item}
and prod.channel_id in
#{item}
and (prod.original_text_scene like concat('%',#{paramModel.keywords},'%') or prod.input_data_id like concat('%',#{paramModel.keywords},'%'))
and prod.model_type = #{paramModel.modelType}
and prod.content_type in
#{item}
order by prod.create_time desc

